mapper.select:
select id, xid, status, expire_time, retry_count, create_time, update_time
from tcc_transaction
where xid = #{xid}

mapper.update:
update tcc_transaction
set status = #{status}
where xid = #{xid}

mapper.select:
select id, xid, status, expire_time, retry_count, create_time, update_time
from tcc_transaction
where status = #{status}
order by create_time asc
limit #{limit}

select id, xid, branch_id, status, payload, error_message, next_retry_time, retry_count, create_time,
       update_time
from tcc_branch
where xid = #{xid}
  and branch_id = #{branchId}

mapper.update:
update tcc_branch
set status        = #{status},
    error_message = ifnull(#{errorMessage}, '')
where xid = #{xid}
  and branch_id = #{branchId}

mapper.select:
select id, xid, branch_id, status, payload, error_message, next_retry_time, retry_count, create_time,
       update_time
from tcc_branch
where status = #{status}
  and next_retry_time <= now()
limit #{limit}
